"""Build the CMS CMS new job form .robot files from data/testcases_job_new.csv.

Run:  python tools/csv_to_robot_job_new.py [path/to/testcases_job_new.csv]

* Same idea as tools/csv_to_robot_dashboard.py: the CSV is the source of truth for ID, description,
  expected result and type. STEPS maps each ID to its keywords and file group.
* Writes tests/job_new/*.robot (the other test folders are not touched).
* Do not hand-edit the generated files; edit STEPS or resources/pages/job_new.resource instead.
"""
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from csv_to_robot import read_cases, render_test  # noqa: E402

ROOT = Path(__file__).resolve().parent.parent
DEFAULT_CSV = ROOT / "data" / "testcases_job_new.csv"
OUT_DIR = ROOT / "tests" / "job_new"
PREFIX = "JN"

GROUPS = {
    "open": ("01_open", "Open the form, top of the page and leaving it"),
    "form": ("02_form", "Labels, default values and lists"),
    "editors": ("03_editors", "The three rich text boxes"),
    "status": ("04_status", "Publishing status and closing date"),
    "meta": ("05_metadata", "Type, urgent badge, vacancies and map"),
    "validation": ("06_validation", "What the browser refuses (nothing is saved)"),
    "layout": ("07_keyboard_layout", "Keyboard and screen sizes"),
}
MANUAL_FILE = "99_manual"

# JN id -> (group, [steps])
STEPS = {
    "JN001": ("open", ["New Job Form Should Open From The List"]),
    "JN002": ("open", ["New Job Heading Should Match"]),
    "JN003": ("open", ["Top Bar Should Show Brand And User", "Menu Texts Should Match", "Jobs Menu Should Be The Current Page"]),
    "JN004": ("open", ["New Job Form Should Ask For Login When Logged Out"]),
    "JN005": ("open", ["Link Should Return To The Job List    ${JN_BACK_LINK}    ${JN_BACK_TEXT}"]),
    "JN006": ("open", ["Link Should Return To The Job List    ${JN_CANCEL}    ${JN_CANCEL_TEXT}"]),
    "JN007": ("open", ["Leaving The Form Should Not Create A Job"]),
    "JN008": ("open", ["Refresh Should Give An Empty Form"]),
    "JN009": ("form", ["Section Headings And Notes Should Show"]),
    "JN010": ("form", ["Field Labels Should Match"]),
    "JN011": ("form", ["Title Should Start Empty"]),
    "JN012": ("form", ["Other Fields Should Start With Defaults"]),
    "JN013": ("form", ["Default Deadline Should Be Thirty Days Away"]),
    "JN014": ("form", ["Sample Text Should Be In The Editors"]),
    "JN015": ("form", ["Lists Should Have The Right Choices"]),
    "JN016": ("form", ["Benefits Should Be Listed And Unticked"]),
    "JN017": ("form", ["Benefits Should Be Tickable"]),
    "JN018": ("form", ["Required Fields Should Be Marked Required"]),
    "JN019": ("editors", ["Editors Should Sync The Hidden Fields"]),
    "JN020": ("editors", ["Special Characters Should Be Escaped"]),
    "JN021": ("editors", ["Bold Button Should Make Text Bold"]),
    "JN022": ("editors", ["List Buttons Should Make Lists"]),
    "JN023": ("editors", ["Heading Choice Should Make A Heading"]),
    "JN024": ("editors", ["Emptying An Editor Should Empty The Hidden Fields"]),
    "JN025": ("editors", ["Every Editor Should Have Its Toolbar"]),
    "JN026": ("status", ["Default Status Should Be Open"]),
    "JN027": ("status", ["Manual Toggle Should Close The Job"]),
    "JN028": ("status", ["Past Deadline Should Show Auto Expired"]),
    "JN029": ("status", ["Today Should Still Be Open"]),
    "JN030": ("status", ["Past Deadline Should Win Over The Manual Toggle"]),
    "JN031": ("status", ["Deadline Box Should Need A Date"]),
    "JN032": ("meta", ["Internship Type Should Move The Job To The Internship Tab"]),
    "JN033": ("meta", ["Urgent Box Should Set The Hidden Field"]),
    "JN034": ("meta", ["Vacancies Box Should Take Whole Numbers From One"]),
    "JN035": ("meta", ["Coordinates Should Take Decimal Numbers"]),
    "JN036": ("meta", ["Maps Link Should Follow The Coordinates"]),
    "JN037": ("validation", ["Empty Title Should Be Refused"]),
    "JN038": ("validation", ["Each Required Box Left Empty Should Be Invalid"]),
    "JN039": ("validation", ["Whole Form Should Be Invalid Only Because Of The Title"]),
    "JN040": ("layout", ["Main Fields Should Follow The Tab Order"]),
    "JN041": ("layout", ["Status Panel Should Sit Beside The Form"]),
    "JN042": ("layout", ["Status Panel Should Sit Below The Form    768    1024", "Page Should Not Scroll Sideways    768    1024"]),
    "JN043": ("layout", ["Page Should Not Scroll Sideways    375    812"]),
}

# Behaviour read from the dev site (or an expectation of mine) that the team must confirm.
ASSUMPTION_IDS = {"JN013", "JN014", "JN030", "JN040", "JN041", "JN042"}


def file_header(title, ids, manual=False):
    out = ["*** Settings ***",
           f"Documentation     {title} ({ids[0]} to {ids[-1]}). GENERATED by tools/csv_to_robot_job_new.py - do not edit."]
    if manual:
        out += ["Test Tags         manual"]
    else:
        out += ["Resource          ../../resources/all_pages.resource",
                "Suite Setup       Open New Job Browser",
                "Suite Teardown    Close All Browsers",
                "Test Setup        Open New Job Form",
                "Test Tags         automate    job-new    needs-account"]
    return "\n".join(out) + "\n\n\n*** Test Cases ***\n"


def main():
    csv_path = Path(sys.argv[1]) if len(sys.argv) > 1 else DEFAULT_CSV
    cases = read_cases(csv_path, PREFIX)
    auto = [c for c in cases if c["type"] == "automate"]
    manual = [c for c in cases if c["type"] == "manual"]

    missing = [c["id"] for c in auto if c["id"] not in STEPS]
    extra = [i for i in STEPS if i not in {c["id"] for c in auto}]
    if missing or extra:
        sys.exit(f"STEPS mismatch. In CSV as automate but no steps: {missing}. Steps but not automate in CSV: {extra}")

    OUT_DIR.mkdir(parents=True, exist_ok=True)
    for old in OUT_DIR.glob("*.robot"):
        old.unlink()

    by_group = {g: [] for g in GROUPS}
    for case in auto:
        group, steps = STEPS[case["id"]]
        tags = [case["id"], group]
        if case["id"] in ASSUMPTION_IDS:
            tags.append("assumption")
        by_group[group].append(render_test(case, steps, tags))

    for group, (filename, title) in GROUPS.items():
        tests = by_group[group]
        ids = [t.split()[0] for t in tests]
        body = file_header(title, ids) + "\n\n".join(tests) + "\n"
        (OUT_DIR / f"{filename}.robot").write_text(body, encoding="utf-8", newline="\n")

    manual_tests = [
        render_test(c, ["Skip    Manual case: run by hand and record the result in the CSV"], [c["id"], "manual"])
        for c in manual
    ]
    ids = [c["id"] for c in manual]
    body = file_header("Manual cases (always skipped)", ids, manual=True) + "\n\n".join(manual_tests) + "\n"
    (OUT_DIR / f"{MANUAL_FILE}.robot").write_text(body, encoding="utf-8", newline="\n")

    print(f"automate: {len(auto)}  manual: {len(manual)}  total: {len(cases)}")
    for group, (filename, _) in GROUPS.items():
        print(f"  job_new/{filename}.robot  {len(by_group[group])}")
    print(f"  job_new/{MANUAL_FILE}.robot  {len(manual)}")


if __name__ == "__main__":
    main()
